    response: (_data, matches, output) => {
      // cactbot-builtin-response
      output.responseOutputStrings = {
        square: {
          en: '#${num} Square',
          de: '#${num} Viereck',
          fr: '#${num} Carré',
          ja: '#${num} 四角',
          cn: '#${num} (男)',
          ko: '#${num} 짝수',
          tc: '#${num} (男)'
        },
        triangle: {
          en: '#${num} Triangle',
          de: '#${num} Dreieck',
          fr: '#${num} Triangle',
          ja: '#${num} 三角',
          cn: '#${num} （女）',
          ko: '#${num} 홀수',
          tc: '#${num} （女）'
        }
      };
      const id = matches.id;
      if (!id) return;
      let num = parseInt(id);
      const isTriangle = num >= 95;
      num -= 90;
      if (isTriangle) num -= 4;

      // Odd numbers have to run to the other side, so make this louder.
      // TODO: should this be alarm/alert instead of alert/info?
      const isOdd = num % 2;
      const text = isTriangle ? output.triangle({
        num: num
      }) : output.square({
        num: num
      });
      return {
        [isOdd ? 'alertText' : 'infoText']: text
      };
    }
