    id: 'O12S Archive All No Marker',
    type: 'HeadMarker',
    netRegex: {
      id: ['003E', '0060'],
      capture: false
    },
    condition: data => {
      // 4 fire markers, 1 stack marker.
      if (!data.isFinalOmega) return false;
      return data.archiveMarkers && Object.keys(data.archiveMarkers).length === 5;
    },
    infoText: (data, _matches, output) => {
      if (data.me in (data.archiveMarkers ?? {})) return;
      for (const player in data.archiveMarkers) {
        if (data.archiveMarkers[player] !== '003E') continue;
        return output.text({
          player: data.party.member(player)
        });
      }
    },
    outputStrings: {
      text: outputs/* default.stackOnPlayer */.Z.stackOnPlayer
    }
