const gaolConfig = id => {
  // Since these are all explicit string types, get the number from the string.
  const numStr = id.replace('gaolOrder', '');
  return {
    id: id,
    name: {
      en: `Titan Gaol Order ${numStr}`,
      de: `Titan Gefängnis Reihenfolge ${numStr}`,
      fr: `Ordre geôle de Titan ${numStr}`,
      ja: `ジェイルの順番 ${numStr}`,
      cn: `泰坦石牢顺序 ${numStr}`,
      ko: `돌감옥 순서 ${numStr}`,
      tc: `泰坦石牢順序 ${numStr}`
    },
    type: 'string',
    default: ''
  };
};

