    preRun: (data, matches) => {
      data.titanGaols.push(matches.target);
      if (data.titanGaols.length !== 3) return;
      const rawGaolOrder = [data.triggerSetConfig.gaolOrder1, data.triggerSetConfig.gaolOrder2, data.triggerSetConfig.gaolOrder3, data.triggerSetConfig.gaolOrder4, data.triggerSetConfig.gaolOrder5, data.triggerSetConfig.gaolOrder6, data.triggerSetConfig.gaolOrder7, data.triggerSetConfig.gaolOrder8, data.triggerSetConfig.gaolOrder9, data.triggerSetConfig.gaolOrder10, data.triggerSetConfig.gaolOrder11, data.triggerSetConfig.gaolOrder12, data.triggerSetConfig.gaolOrder13, data.triggerSetConfig.gaolOrder14, data.triggerSetConfig.gaolOrder15, data.triggerSetConfig.gaolOrder16, data.triggerSetConfig.gaolOrder17, data.triggerSetConfig.gaolOrder18, data.triggerSetConfig.gaolOrder19, data.triggerSetConfig.gaolOrder20].map(x => x.trim()).filter(x => x !== '');
      const partyNames = [...data.party.partyNames].sort((a, b) => a.localeCompare(b));

      // Merge jobs and names into a single list of names.
      const gaolOrder = [];
      for (const entry of rawGaolOrder) {
        if (entry.length !== 3) {
          gaolOrder.push(entry.toLocaleLowerCase());
          continue;
        }
        const uppercaseJobEntry = entry.toUpperCase();
        for (const name of partyNames) {
          const jobStr = data.party.jobName(name);
          if (jobStr === uppercaseJobEntry) gaolOrder.push(name.toLocaleLowerCase());
        }
      }
      data.titanGaols.sort((a, b) => {
        // Sort by `gaolOrder` and then alphabetical for names not in the list.
        const aIdx = gaolOrder.indexOf(a.toLocaleLowerCase());
        const bIdx = gaolOrder.indexOf(b.toLocaleLowerCase());
        if (aIdx === -1 && bIdx !== -1) return 1;
        if (bIdx === -1 && aIdx !== -1) return -1;
        if (aIdx < bIdx) return -1;
        if (bIdx < aIdx) return 1;
        return a.localeCompare(b);
      });
      if (data.options.Debug) {
        console.log(`GAOL CONFIG: ${JSON.stringify(rawGaolOrder)}`);
        console.log(`GAOL CONFIG NAME ORDER: ${JSON.stringify(gaolOrder)}`);
        console.log(`GAOL FINAL ORDER: ${JSON.stringify(data.titanGaols)}`);
      }
    },
