      const rows = data.unseenBadRows;
      const cols = data.unseenBadCols;
      if (!rows || !cols) return;
      if (data.avowedPhase === 'bow') {
        // consider asserting that badCols are 0, 2, 4 here.
        if (rows.includes(2)) return output.bowLight();
        return output.bowDark();
      }
      if (data.avowedPhase !== 'staff') return;
      if (cols.includes(1)) {
        if (rows.includes(1)) return output.staffOutsideCorner();
        return output.staffOutsideColInsideRow();
      }
      if (cols.includes(0)) {
        if (rows.includes(0)) return output.staffInsideCorner();
        return output.staffInsideColOutsideRow();
      }
