const boundOfFaithFireTetherResponse = (data, _matches, output) => {
  // cactbot-builtin-response
  output.responseOutputStrings = {
    stackOnYou: outputs/* default.stackOnYou */.Z.stackOnYou,
    stackOnPlayer: outputs/* default.stackOnPlayer */.Z.stackOnPlayer,
    unknownTarget: outputs/* default.unknown */.Z.unknown
  };
  const targets = Object.keys(data.tethers || {});
  if (targets.includes(data.me)) return {
    alertText: output.stackOnYou()
  };
  if (targets.length === 0) return {
    alertText: output.stackOnPlayer({
      player: output.unknownTarget()
    })
  };
  return {
    alertText: output.stackOnPlayer({
      player: data.party.member(targets[0])
    })
  };
};
