    run: (data, matches) => {
      const color = mirrorFlags[matches.flags];
      const location = mirrorLocs[matches.location];
      if (color === undefined || location === undefined) return;
      data.mirrors.push({
        color,
        location
      });
      data.mirrorMap[location] = color;
    }
