      const partyNames = data.party.partyNames;
      const nonTethers = partyNames.filter(x => !tethers.includes(x));
      const [stack1, stack2] = nonTethers;
      const other = data.party.member(stack1 === data.me ? stack2 : stack1);
      return output.stack({
        player: other
      });
