    id: 'AAI Statice Pinwheeling Dartboard Color',
    type: 'AddedCombatant',
    netRegex: {
      npcNameId: '12507'
    },
    durationSeconds: 6,
    response: (data, matches, output) => {
      // cactbot-builtin-response
      output.responseOutputStrings = {
        dartOnYou: {
          en: 'Dart (w/${player})',
          de: 'Dart (mit ${player})',
          fr: 'Dard (avec ${player})',
          cn: '飞镖 (和 ${player})',
          ko: '다트 (+ ${player})',
          tc: '飛鏢 (和 ${player})'
        },
        noDartOnYou: {
          en: 'No Dart',
          de: 'Kein Dart',
          fr: 'Pas de dard',
          cn: '无飞镖',
          ko: '다트 없음',
          tc: '無飛鏢'
        },
        blue: {
          en: 'Avoid Blue',
          de: 'Vermeide Blau',
          fr: 'Évitez le bleu',
          cn: '躲避蓝色',
          ko: '파란색 피하기',
          tc: '躲避藍色'
        },
        red: {
          en: 'Avoid Red',
          de: 'Vermeide Rot',
          fr: 'Évitez le rouge',
          cn: '躲避红色',
          ko: '빨간색 피하기',
          tc: '躲避紅色'
        },
        yellow: {
          en: 'Avoid Yellow',
          de: 'Vermeide Gelb',
          fr: 'Évitez le jaune',
          cn: '躲避黄色',
          ko: '노란색 피하기',
          tc: '躲避黃色'
        }
      };
      let infoText;
      const centerX = -200;
      const centerY = 0;
      const x = parseFloat(matches.x) - centerX;
      const y = parseFloat(matches.y) - centerY;

      // 12 pie slices, the edge of the first one is directly north.
      // It goes in B R Y order repeating 4 times.
      // The 0.5 subtraction (12 - 0.5 = 11.5) is because the Homing Pattern
      // lands directly in the middle of a slice.
      const dir12 = Math.round(6 - 6 * Math.atan2(x, y) / Math.PI + 11.5) % 12;
      const colorOffset = dir12 % 3;
      const colorMap = {
        0: 'blue',
        1: 'red',
        2: 'yellow'
      };
      data.staticeHomingColor = colorMap[colorOffset];
      if (data.staticeHomingColor !== undefined) infoText = output[data.staticeHomingColor]();
      if (data.staticeDart.length !== 2) return {
        infoText
      };
      const dartTargets = data.staticeDart.map(x => x.target);
      if (!dartTargets.includes(data.me)) return {
        alertText: output.noDartOnYou(),
        infoText: infoText
      };
      const [target1, target2] = dartTargets;
      if (target1 === undefined || target2 === undefined) return {
        infoText
      };
      const otherTarget = data.party.member(target1 === data.me ? target2 : target1);
      return {
        alertText: output.dartOnYou({
          player: otherTarget
        }),
        infoText: infoText
      };
    }
