      const x = Math.round((parseFloat(matches.x) - 100) / 7.5);
      const y = Math.round((parseFloat(matches.y) - 100) / 7.5);
      const directions = {
        '0,1': 'dirSW',
        '1,0': 'dirSE',
        '0,-1': 'dirNE',
        '-1,0': 'dirNW'
      };
      const direction = directions[`${x},${y}`];
      if (direction === undefined) return;
      if (matches.id === '76E7') data.topazRayDirections[0] = direction;
      if (matches.id === '76EA') data.topazRayDirections[1] = direction;
      if (data.topazRayDirections[0] === undefined || data.topazRayDirections[1] === undefined) return;
      const dir0Str = output[data.topazRayDirections[0]]();
      const dir1Str = output[data.topazRayDirections[1]]();
      return output.text({
        start: dir1Str,
        end: dir0Str
      });
