const get5HeadSafeDir = (posX, posY, output) => {
  // NOTE: in both this function and the other safe dir, it's probably not possible to have the head facing
  // exactly where the knockback destination / aoe safe zone is.  For completionism, we'll add some
  // instruction but this probably can't happen.

  if (posX < 100) {
    if (posY < 100) return output.nw();
    return output.sw();
  }
  if (posY < 100) return output.ne();
  return output.se();
};
const getKBOrbSafeDir = (posX, posY, output, head8Dir) => {
  if (head8Dir === undefined || head8Dir % 2 === 0) head8Dir = headDir.none;

  // NOTE: in both this function and the other safe dir, it's probably not possible to have the head facing
  // exactly where the knockback destination / aoe safe zone is.  For completionism, we'll add some
  // instruction but this probably can't happen.  Additionally, since "SW", "S", and "SE" are not really
  // melee uptime friendly, try to call "W", "N", and "E" as the head safe spots.

  if (posX < 100) {
    if (posY < 100) {
      const mainDir = output.nw();
      return {
        [headDir.none]: output.knockback({
          dir: mainDir
        }),
        [headDir.ne]: output.knockbackWithHead({
          dir1: mainDir,
          dir2: output.s()
        }),
        [headDir.se]: output.knockbackWithHead({
          dir1: mainDir,
          dir2: output.w()
        }),
        [headDir.sw]: output.knockbackWithHead({
          dir1: mainDir,
          dir2: output.e()
        }),
        [headDir.nw]: output.knockback({
          dir: mainDir
        })
      }[head8Dir];
    }
    const mainDir = output.sw();
    return {
      [headDir.none]: output.knockback({
        dir: mainDir
      }),
      [headDir.ne]: output.knockbackWithHead({
        dir1: mainDir,
        dir2: output.w()
      }),
      [headDir.se]: output.knockbackWithHead({
        dir1: mainDir,
        dir2: output.n()
      }),
      [headDir.sw]: output.knockback({
        dir: mainDir
      }),
      [headDir.nw]: output.knockbackWithHead({
        dir1: mainDir,
        dir2: output.e()
      })
    }[head8Dir];
  }
  if (posY < 100) {
    const mainDir = output.ne();
    return {
      [headDir.none]: output.knockback({
        dir: mainDir
      }),
      [headDir.ne]: output.knockback({
        dir: mainDir
      }),
      [headDir.se]: output.knockbackWithHead({
        dir1: mainDir,
        dir2: output.w()
      }),
      [headDir.sw]: output.knockbackWithHead({
        dir1: mainDir,
        dir2: output.e()
      }),
      [headDir.nw]: output.knockbackWithHead({
        dir1: mainDir,
        dir2: output.s()
      })
    }[head8Dir];
  }
  const mainDir = output.se();
  return {
    [headDir.none]: output.knockback({
      dir: mainDir
    }),
    [headDir.ne]: output.knockbackWithHead({
      dir1: mainDir,
      dir2: output.w()
    }),
    [headDir.se]: output.knockback({
      dir: mainDir
    }),
    [headDir.sw]: output.knockbackWithHead({
      dir1: mainDir,
      dir2: output.n()
    }),
    [headDir.nw]: output.knockbackWithHead({
      dir1: mainDir,
      dir2: output.e()
    })
  }[head8Dir];
};
