      const isSafe1Safe = terrastormDir === 'nw' && safe1 !== 'nw' && safe1 !== 'se' || terrastormDir === 'ne' && safe1 !== 'ne' && safe1 !== 'sw';
      const isSafe2Safe = terrastormDir === 'nw' && safe2 !== 'nw' && safe2 !== 'se' || terrastormDir === 'ne' && safe2 !== 'ne' && safe2 !== 'sw';
      if (isSafe1Safe && isSafe2Safe || !isSafe1Safe && !isSafe2Safe) return;
