const the_omega_protocol_playstationHeadmarkerIds = [the_omega_protocol_headmarkers.firechainCircle, the_omega_protocol_headmarkers.firechainTriangle, the_omega_protocol_headmarkers.firechainSquare, the_omega_protocol_headmarkers.firechainX];
const the_omega_protocol_playstationMarkerMap = {
  [the_omega_protocol_headmarkers.firechainCircle]: 'circle',
  [the_omega_protocol_headmarkers.firechainTriangle]: 'triangle',
  [the_omega_protocol_headmarkers.firechainSquare]: 'square',
  [the_omega_protocol_headmarkers.firechainX]: 'cross'
};
const the_omega_protocol_firstMarker = parseInt('0017', 16);
const the_omega_protocol_getHeadmarkerId = (data, matches) => {
  if (data.decOffset === undefined) data.decOffset = parseInt(matches.id, 16) - the_omega_protocol_firstMarker;
  // The leading zeroes are stripped when converting back to string, so we re-add them here.
  // Fortunately, we don't have to worry about whether or not this is robust,
  // since we know all the IDs that will be present in the encounter.
  return (parseInt(matches.id, 16) - data.decOffset).toString(16).toUpperCase().padStart(4, '0');
};
