// Function to find a safe spot in Primordial Chaos
// Expected inputs are the dirNums of two oozes
const deadStarsFindSafeSpot = (ooze1, ooze2) => {
  // Filter from map of valid ooze locations where oozes are
  const safeDirNums = [1, 3, 5, 7].filter(dirNum => {
    return dirNum !== ooze1 && dirNum !== ooze2;
  });
  const safe1 = safeDirNums[0];
  const safe2 = safeDirNums[1];
  if (safe1 === 7 && safe2 === 1 || safe1 === 1 && safe2 === 7) return 0; // North
  if (safe1 === 1 && safe2 === 3 || safe1 === 3 && safe2 === 1) return 2; // East
  if (safe1 === 3 && safe2 === 5 || safe1 === 5 && safe2 === 3) return 4; // South
  if (safe1 === 5 && safe2 === 7 || safe1 === 7 && safe2 === 5) return 6; // West
  if (safe1 === 3 && safe2 === 7 || safe1 === 7 && safe2 === 3) return 3; // Also northwest
  if (safe1 === 1 && safe2 === 5 || safe1 === 5 && safe2 === 1) return 1; // Also southwest
  return -1;
};
// Used with deadStarsFindSafeSpot to map to longform direction
const deadStarsMapOutput = ['north', 'northeast', 'east', 'southeast', 'south', 'southwest', 'west', 'northwest', 'unknown'];

