// Return the combatant's platform by number
const getPlatformNum = (x, y) => {
  // S Platform
  if (x > 90 && x < 108 && y > 107) return 0;

  // SW Platform
  if (x <= 92 && y > 95) return 1;

  // NW Platform
  if (x <= 100 && y <= 95) return 2;

  // NE Platform
  if (x > 100 && y <= 95) return 3;

  // SE Platform
  if (x >= 109 && y > 95) return 4;
  return -1;
};
const getFangPlatform = combatant => {
  const x = combatant.PosX;
  const y = combatant.PosY;

  // S Platform
  // (96, 126.5) Left and (104, 126.5) Right
  if (x > 95 && x < 105 && y > 125) return 0;

  // SW Platform
  // (73.56, 104.38) Left and (76.03, 111.99) Right
  if (x > 72 && x < 77 && y > 103 && y < 113) return 1;

  // NW Platform
  // (87.66, 76.20) Left and (81.19, 80.91) Right
  if (x > 80 && x < 89 && y > 75 && y < 82) return 2;

  // NE Platform
  // (118.81, 80.91) Left and (112.34, 76.2) Right
  if (x > 111 && x < 120 && y > 75 && y < 82) return 3;

  // SE Platform
  // (123.97, 111.99) Left and (126.44, 104.38) Right
  if (x > 122 && x < 128 && y > 103 && y < 113) return 4;
  return -1;
};

// Find the actor on the platform we want
const findFang = (actors, platform) => {
  for (const actor of actors) {
    const actorPlatform = getFangPlatform(actor);
    if (platform === actorPlatform) {
      return actor;
    }
  }

  // Did not find actor on the platform
  return undefined;
};
