      // we're done collecting, so we only care about personal debuffs now
      if (data.me !== matches.target) return;
      if (debuff === 'wind') data.p4CTMyRole = 'redWind';else if (debuff === 'water') data.p4CTMyRole = 'blueWater';else if (debuff === 'unholy') data.p4CTMyRole = 'blueUnholy';else if (debuff === 'eruption') data.p4CTMyRole = 'blueEruption';
      // if redIce/blueIce, data.p4CTMyRole gets set in the Debuff trigger below.
